WITH filtered AS (SELECT *, CONCAT_WS('-', level, full_name) level_full_name_key, TRIM(full_name) clean_full_name, COALESCE(job_title, 'UNKNOWN') job_title_clean FROM employees WHERE hire_date > DATE '2024-02-29' AND level IS NOT NULL AND level IN ('L1', 'L3')) SELECT * FROM (SELECT dept_id, level, salary FROM filtered) src PIVOT (AVG(salary) AS value_sum, COUNT(1) AS cnt FOR level IN ('L4', 'L5'))
